CREATE TYPE "BusinessType" AS ENUM ('INTERIOR_CONSTRUCTION','RETAIL_TRADING','SERVICE_BUSINESS','MANUFACTURING','OTHER_MIXED');
CREATE TYPE "AccountModule" AS ENUM ('QUOTATIONS_BOQ','SALES','SALES_ORDER','PROFORMA_INVOICE','DELIVERY_CHALLAN','CREDIT_NOTE','CUSTOMER_RECEIPTS','CUSTOMER_ADVANCES','PAYMENT_REMINDERS','PURCHASES','PURCHASE_ORDER','PURCHASE_BILLS','DEBIT_NOTE','VENDOR_PAYMENTS','VENDOR_ADVANCES','SUBCONTRACTORS','PROJECTS','PROJECT_COSTING','INVENTORY','BARCODE','EXPENSES','ASSETS','GST_ADVANCED');
CREATE TYPE "CommercialDocumentType" AS ENUM ('SALES_ORDER','PROFORMA_INVOICE','SALES_INVOICE','DELIVERY_CHALLAN','CREDIT_NOTE','PURCHASE_ORDER','PURCHASE_BILL','DEBIT_NOTE','SUBCONTRACT_PURCHASE');
CREATE TYPE "CommercialDocumentStatus" AS ENUM ('DRAFT','POSTED','CANCELLED'); CREATE TYPE "SettlementType" AS ENUM ('CUSTOMER_RECEIPT','CUSTOMER_ADVANCE','VENDOR_PAYMENT','VENDOR_ADVANCE');
ALTER TABLE "account_settings" ADD COLUMN "businessType" "BusinessType" NOT NULL DEFAULT 'OTHER_MIXED', ADD COLUMN "enabledModules" "AccountModule"[] NOT NULL DEFAULT ARRAY[]::"AccountModule"[];
UPDATE "account_settings" s SET "enabledModules"=ARRAY['QUOTATIONS_BOQ','SALES','SALES_ORDER','PROFORMA_INVOICE','DELIVERY_CHALLAN','CREDIT_NOTE','CUSTOMER_RECEIPTS','CUSTOMER_ADVANCES','PAYMENT_REMINDERS','PURCHASES','PURCHASE_ORDER','PURCHASE_BILLS','DEBIT_NOTE','VENDOR_PAYMENTS','VENDOR_ADVANCES','SUBCONTRACTORS']::"AccountModule"[] FROM "companies" c WHERE c.id=s."companyId" AND c."productEdition" IN ('SALESPUNCH360_ACCOUNT','SALESPUNCH360_PLUS');
CREATE TABLE "commercial_documents" ("id" UUID PRIMARY KEY,"companyId" UUID NOT NULL,"branchId" UUID NOT NULL,"type" "CommercialDocumentType" NOT NULL,"status" "CommercialDocumentStatus" NOT NULL DEFAULT 'DRAFT',"documentNumber" TEXT NOT NULL,"partyId" UUID NOT NULL,"partyName" TEXT NOT NULL,"issueDate" DATE NOT NULL,"dueDate" DATE,"subtotal" DECIMAL(18,2) NOT NULL,"taxTotal" DECIMAL(18,2) NOT NULL,"grandTotal" DECIMAL(18,2) NOT NULL,"balanceDue" DECIMAL(18,2) NOT NULL,"notes" TEXT,"journalEntryId" UUID,"createdById" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "commercial_document_lines" ("id" UUID PRIMARY KEY,"companyId" UUID NOT NULL,"documentId" UUID NOT NULL,"position" INTEGER NOT NULL,"description" TEXT NOT NULL,"quantity" DECIMAL(18,4) NOT NULL,"rate" DECIMAL(18,2) NOT NULL,"taxRate" DECIMAL(7,4) NOT NULL DEFAULT 0,"taxable" DECIMAL(18,2) NOT NULL,"taxAmount" DECIMAL(18,2) NOT NULL,"total" DECIMAL(18,2) NOT NULL);
CREATE TABLE "account_settlements" ("id" UUID PRIMARY KEY,"companyId" UUID NOT NULL,"branchId" UUID NOT NULL,"type" "SettlementType" NOT NULL,"partyId" UUID NOT NULL,"amount" DECIMAL(18,2) NOT NULL,"transactionDate" DATE NOT NULL,"reference" TEXT,"journalEntryId" UUID,"createdById" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "payment_reminders" ("id" UUID PRIMARY KEY,"companyId" UUID NOT NULL,"documentId" UUID NOT NULL,"remindAt" TIMESTAMP(3) NOT NULL,"message" VARCHAR(1000) NOT NULL,"sentAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "commercial_documents_companyId_id_key" ON "commercial_documents"("companyId","id"); CREATE UNIQUE INDEX "commercial_documents_companyId_branchId_type_documentNumber_key" ON "commercial_documents"("companyId","branchId","type","documentNumber"); CREATE UNIQUE INDEX "commercial_document_lines_companyId_documentId_position_key" ON "commercial_document_lines"("companyId","documentId","position");
ALTER TABLE "commercial_documents" ADD FOREIGN KEY("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT, ADD FOREIGN KEY("companyId","branchId") REFERENCES "branches"("companyId","id") ON DELETE RESTRICT, ADD FOREIGN KEY("companyId","createdById") REFERENCES "users"("companyId","id") ON DELETE RESTRICT;
ALTER TABLE "commercial_document_lines" ADD FOREIGN KEY("companyId","documentId") REFERENCES "commercial_documents"("companyId","id") ON DELETE RESTRICT; ALTER TABLE "account_settlements" ADD FOREIGN KEY("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT, ADD FOREIGN KEY("companyId","branchId") REFERENCES "branches"("companyId","id") ON DELETE RESTRICT, ADD FOREIGN KEY("companyId","createdById") REFERENCES "users"("companyId","id") ON DELETE RESTRICT; ALTER TABLE "payment_reminders" ADD FOREIGN KEY("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT, ADD FOREIGN KEY("companyId","documentId") REFERENCES "commercial_documents"("companyId","id") ON DELETE RESTRICT;
